function [mdot] = rcs_mass_flow(fs, thrust, isp)
%RCS_MASS_FLOW  The propellant flow [kg/s] of the couples' summed scaled duty fs, thrust [N] and specific impulse [s].
%   fs: real[1] (passed a plain number)
%   thrust: real[N] (passed in m kg/s^2)
%   isp: real[s] (passed in s)
%   returns mdot: real[kg/s] (passed in kg/s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    mdot = 0;
    mdot = (((fs * 2) * thrust) / (isp * 9.80665));
end
